function useCol(name, q) {
  const [d, setD] = useState(null);
  useEffect(() => (q ? q(db.collection(name)) : db.collection(name)).onSnapshot(
    (s) => setD(s.docs.map((x) => ({ id: x.id, ...x.data() }))),
    (e) => { console.error(e); setD([]); }
  ), [name]);
  return d;
}

const fileToDataUrl = (file, max = 900, q = 0.72) => new Promise((res, rej) => {
  const r = new FileReader();
  r.onerror = () => rej(new Error('read'));
  r.onload = () => {
    const img = new Image();
    img.onerror = () => rej(new Error('img'));
    img.onload = () => {
      const k = Math.min(1, max / Math.max(img.width, img.height));
      const w = Math.round(img.width * k), h = Math.round(img.height * k);
      const c = document.createElement('canvas');
      c.width = w; c.height = h;
      c.getContext('2d').drawImage(img, 0, 0, w, h);
      let out = c.toDataURL('image/jpeg', q);
      if (out.length > 600000) out = c.toDataURL('image/jpeg', 0.5);
      res(out);
    };
    img.src = r.result;
  };
  r.readAsDataURL(file);
});

